/// Four nops after every instruction of the .text section.
std::string padded(const char *program)
{
    std::istringstream in(program);
    std::string line, out;
    bool text = false;
    while (std::getline(in, line))
    {
        out += line + "\n";
        if (line == ".text")
            text = true;
        else if (text && line.rfind("    ", 0) == 0)
            out += "    nop\n    nop\n    nop\n    nop\n";
    }
    return out;
}
