class Fflags : public testing::TestWithParam<IsaParam>
{
};

INSTANTIATE_TEST_SUITE_P(AllModels, Fflags, testing::ValuesIn(isaParams(kCases, allModels())),
                         [](const testing::TestParamInfo<IsaParam> &info)
                         { return isaParamName(kCases, info.param); });

TEST_P(Fflags, EachOpRaisesTheSpecFlagsAndTheyAccrue)
{
    QTemporaryDir dir;
    ASSERT_TRUE(dir.isValid());
    const IsaCase &c = kCases[GetParam().index];
    const std::string program = padded(c.program);
    IsaCase run = c;
    run.program = program.c_str();
    expectIsaCase(run, GetParam().model, dir);
}
